from collections import deque

class PointManager:
    def __init__(self):
        self.points = []

    def add_point(self, x, y):
        self.points.append((x, y))

    def remove_point(self, x, y):
        self.points = [p for p in self.points if p[0] != x or p[1] != y]

    def find_next_point(self, x, y):
        q = deque(self.points)
        while q:
            p = q.popleft()
            if p[0] > x and p[1] > y:
