To solve this problem, we can use Dijkstra's algorithm to find the shortest path from the hostel to all buildings. Then, we can calculate the total distance Chef needs to travel for each day by adding the distance to the required number of subjects to pass the semester.

Here's the Python program to solve the problem:

```python
import heapq

def dijkstra(graph, start, end):
    heap = [(0, start)]
    distance = {node: float('infinity') for node in graph}
    distance[start] = 0
    while heap:
        current_distance, current_node = heapq.heappop(heap)
        if current_node == end:
            break
        if current_distance > distance[current_node]:
            continue
        for neighbor, weight in graph[current_node].items():
            distance_weight = current_distance + weight
            if distance_weight < distance[neighbor]:
                distance[neighbor] = distance_weight
                heapq.heappush(heap, (distance_weight, neighbor))
    return distance[end]

T = int(input())
for _ in range(T):
    N, M, S, K, buildings, edges, subjects, required, A = map(int, input().split())
    graph = {i: {} for i in range(1, buildings + 1)}
    for _ in range(M):
        u, v = map(int, input().split())
        graph[u][v] = 1
        graph[v][u] = 1
    subject_buildings = [[] for _ in range(subjects)]
    for i in range(1, subjects + 1):
        subject_buildings[A[i] - 1].append(i)
    total_distance = 0
    for i in range(K):
        total_distance += dijkstra(graph, 1, buildings)
        for subject in subject_buildings[i]:
            total_distance += dijkstra(graph, buildings, required[subject - 1])
        if not subject_buildings[i]:
            break
    print(total_distance)
