import sys

def max_score(n, points):
    inf = float('inf')
    dp = [inf] * (10**5 + 10)
    dp[0] = 0

    for x, y, c in points:
        dp[x + y] = min(dp[x + y], dp[x - y] + c)

    ans_x, ans_y = inf, inf
    for i in range(10**5 + 10):
        ans_x = min(ans_x, i - dp[i])
        ans_y = min(ans_y, i + dp[i])

    return ans_y - ans_x

def point_to_square(x, y):
    dx = min(abs(x), y)
    dy = min(x, abs(y))
    return max(dx, dy)

def optimal_square(points):
    total = sum(c for _, _, c in points)
    n = len(points)
    gold_sq = (0, -total//n, 10**5, -total//n)

    for x1, y1, x2, y2 in range(2, max(map(point_to_square, points)) + 1):
        update_total_cost = 0

        # Calculate right total cost possible
        for x, y, c in points:
            if x1 <= x <= x2 and y1 <= y <= y2:
                cost = point_to_square(x) + point_to_square(y)
                if (x1, y1, cost) > gold_sq:
                    gold_sq = (x1, y1, cost)
                update_total_cost += cost

        if gold_sq == (-2, -2, -2, -2):
            return ((x1, y1, x2, y2), 0)

    return ((x1, y1, x2, y2), total - update_total_cost)

