import collections

def solve(strings, k):
    def kmp_prefix_function(string):
        pi = [0] * len(string)
        next = '.'
        for i in range(1, len(string)):
            while (len(next) < i or next != string[i * (next == '.') + i]):
                if next == '.':
                    next = './/' + string[:i]
                else:
                    next = next[1:] + string[i]
            pi[i] = next.index('.')
        return pi

    def matched_pairs(k):
        result = 0
        pairs = collections.defaultdict(list)
        pi = kmp_prefix_function(strings[0])

        for i, _ in enumerate(pi):
            while len(pairs[pi[i]]) > k - 1:
                pairs[pi[i]].pop()
            if i >= k - 1:
                pairs[pi[i]].append(i)
                result += len(pairs[pi[i]])
        return result

    total_matches = 0
    for i, string in enumerate(strings):
        total_matches += matched_pairs(min(len(string), k))
        print(total_matches)

    return total_matches

