import math

def gcd(a, b):
    """Extended Greatest Common Divisor (GCD) of a and b."""
    while b:
        a, b = b, a % b
    return a

def check(password, m, p):
    """Checks if a password is valid based on the given rules."""
    # Check if the password is zero
    if password == 0:
        return False
    # Check if the password and m are coprime
    if gcd(password, m) > 1:
        return False
    # Check if there exist non-negative integers e and k such that p^e = k * m + password
    e = 0
    while p**e < m:
        if p**e == m - (password + (p**e) - 1) // p:
            return True
        e += 1
    return False

def find_passwords(n, m, p):
    """Finds valid password(s) based on the given rules."""
    passwords = []
    for i in range(m):
        if check(i, m, p):
            passwords.append(i)
            if len(passwords) == n:
                break
    if len(passwords) < n:
        print(-1)
    else:
        print(' '.join(map(str, passwords)))

# Example usage:
find_passwords(3, 5, 1)  # Output: 2 4 3
