from math import factorial as fact
from collections import defaultdict

MOD = 998244353

def inverse(n):
    return pow(n, MOD - 2, MOD)

def ncr(n, r):
    r = min(r, n - r)
    return fact(n) * inverse(fact(r)) % MOD * inverse(fact(n - r)) % MOD

def gcd(e, m):
    while m:
        e, m = m, e % m
    return e

def lcm(e1, m1):
    return e1 * (m1 // gcd(e1, m1))

def count_good_subarrays(n):
    mod = 1000000007

    # Calculate gcd for all pairs of subarrays of size i
    subsequences = defaultdict(int)
    for i in range(n):
        for j in range(i + 1, n + 1):
            g = gcd(j - i, n)
            sub = lcm(g, max(j - i, n - (j - i)))
            subsequences[sub] += ncr(j - i + n, j - i)

    # Filter out subarrays that don't allow to create a valid sequence of length 'n'
    good_subarrays = 0
    for sub in subsequences.values():
        good_subarrays += (sub - 1) // n + 1

    return good_subarrays

