@lru_cache(maxsize=None)
def gcd_extended(a, b):
    if b == 0:
        return a, 1, 0
    res = gcd_extended(b, a % b)
    g = res[0]
    s1, s2 = res[1], res[2]
    s2 = g - s2 * (a // b)
    return g, s1, s2

@lru_cache(maxsize=None)
def gcd_mapping(a, b):
    if a == 0:
        return (b := b // 2, 0, 1)
    ba, sa, saa = gcd_mapping(b % a, a)
    return (0, sa, sa - (b - a) * saa)

