def expected_indices(n):
    if n == 1:
        return 1
    total_sum = n * (n + 1) // 2
    iterations_for_sum = inv(n + 1)
    expected = (total_sum - n + 1) * 1 + (n * (n - 1) // 2 - 1 - 1) * iterations_for_sum
