        for j in range(3):
            max_r_consts[j][j] = math.sqrt((i - guess_a)**2 + (guess_b - i)**2)
            max_r_consts[j][2 - j] = math.sqrt((i - guess_a)**2 + (guess_b - i)**2 + 6)

    for i in range(1, n + 1):
        r1 = ((guess_a - i)**2 + (guess_b - i)**2)**0.5
        for j in range(3):
            max_r_consts[j][2 - j] = math.sqrt((i - guess_a)**2 + (guess_b - i)**2)

        if max_r < r1:
            max_r = r1
            best_i = i

    r1 = max_r

    r_taken = [0, 0, 0]

    for i in range(3):
        if max_r_consts[i][i] < r1:
            r_taken[i] += 1
            max_r = max_r_consts[i][2 - i]
        elif max_r_consts[i][2 - i] < r1:
            r_taken[1 - i] += 1

    for i in range(3):
        if max_r_consts[i][i] < r1:
            r_taken[i] += 1
            max_r = max_r_consts[i][2 - i]
        elif max_r_consts[i][2 - i] < r1:
            r_taken[1 - i] += 1
    return best_i, r_taken

def play_game(n, a, b):
    best_a = a
    best_b = b

    for _ in range(600):
        max_r = float('-inf')
        best_i = -1

        for guess_a in range(1, n + 1):
            for guess_b in range(1, n + 1):
                if (best_a > guess_a or (guess_a == best_a and best_b > guess_b)) or (guess_a == best_a and best_b == guess_b):
                    continue
                x, y = query(guess_a, guess_b, n)

                if x == 1:
                    best_a = guess_a
                elif x == 2:
                    best_b = guess_b
                else:
                    max_r = max([guess_a, best_a], [guess_b, best_b], [x, best_a], [y, best_b])
                    best_a = guess_a
                    best_b = guess_b
                    break

        if best_a == a and best_b == b:
            return f'{a} {b}'
        max_i, max_taken = max((i, sum(taken)) for i, taken in enumerate([best_a, guess_a, b, guess_b, best_a, best_b]))
        if 1 in max_taken and 2 in max_taken:
            a = guess_a
        elif 2 in max_taken:
            a = b
        elif 3 in max_taken:
            a = guess_a
        if 1 in max_taken and 3 in max_taken:
            b = guess_b
        elif 3 in max_taken:
            b = best_b
        elif 2 in max_taken:
            b = best_b

    return 'Lost'

