from collections import defaultdict

def find_pairs(text):
    n = len(text)
    pairs = set()
    end_times = defaultdict(list)

    for i in range(n):
        for j in range(min(i+1, n-i), 1, -1):
            substring = text[i-j+1:i+1]
            # Check if substring is a palindrome
            if substring == substring[::-1]:
                pairs.add((i-j+1, i+1))
                end_times[i-j+1].append((i+1, i))

    overlap_count = 0
    for times in end_times.values():
        overlap_count += len(set(times))

    # Memoization for intermediate results
    memo = {('end_times_used', [(1, i)])}
    def count_overlapping_pairs(subset):
        nonlocal memo
        if (subset, tuple(subset)) in memo:
            return memo[subset, tuple(subset)]
        overlaps = set()
        for i, j in subset:
            overlaps.update([(i, j)])
            for x, y in count_overlapping_pairs(subset - {(i, j)}):
                overlaps.update([(i, x), (y, j)])
        memo[subset, tuple(subset)] = len(overlaps)
        return len(overlaps)

    for end, start in end_times.values():
        count_overlapping_pairs(set(end_times[value] for value in end))

    return count_overlapping_pairs(pairs), overlap_count

if __name__ == "__main__":
    n = int(input().strip())
    text = input().strip()
    pairs, overlap_count = find_pairs(text)
    print(pairs - overlap_count)
