from collections import defaultdict

def prefix_function(s):
    """Compute the prefix function of the string s."""
    n = len(s)
    pi = [0] * n
    for i in range(1, n):
        j = pi[i-1]
        while j > 0 and s[i] != s[j]:
            j = pi[j-1]
        if s[i] == s[j]:
            j += 1
        pi[i] = j
    return pi

def substring_count(s, k):
    """Count the number of substrings of length at least k in string s."""
    n = len(s)
    count = 0
    for i in range(n):
        for j in range(i+1, n+1):
            if len(s[i:j]) >= k:
                count += 1
    return count

def solve(strings, k):
    """Solve the problem for the given strings and k."""
    n = len(strings)
    dp_table = defaultdict(int)

    for string in strings:
        pi = prefix_function(string)
        dp_table[substring_count(string, k)] += 1
        for length in range(k, len(string)):
            dp_table[substring_count(string, length)] += dp_table[substring_count(string, length-1)]
        for length in range(k-1, 0, -1):
            dp_table[substring_count(string, length)] += dp_table[substring_count(string, length+1)]

    return [dp_table[len(s)] for s in strings]

