def find_best_answer(round_ans, n):
    min_diff = float('inf')
    best_answer = None
    for a in range(1, n):
        for b in range(1, n):
            if min_diff == abs(a - n) + abs(b - n):
                best_answer = n
                break
            if min_diff > abs(a - n) + abs(b - n):
                best_answer = a
                min_diff = abs(a - n) + abs(b - n)
    for a in range(n+1):
        for b in range(n+1):
            if min_diff == abs(a - n) + abs(b - n):
                best_answer = n
                break
            if min_diff > abs(a - n) + abs(b - n):
                best_answer = a
                min_diff = abs(a - n) + abs(b - n)
    if round_ans == 0:
        for a in range(1, n+1):
            for b in range(1, n+1):
                if min_diff == abs(a - n) + abs(b - n):
                    best_answer = n
                    break
                if min_diff > abs(a - n) + abs(b - n):
                    best_answer = a
                    min_diff = abs(a - n) + abs(b - n)
    return best_answer

