from math import gcd
from functools import reduce
from collections import defaultdict
from functools import lru_cache

MOD = 998244353

@lru_cache(None)
def mod_p(q, n):
    p = pow(q, n, MOD)
    return p

@lru_cache(None)
def nCr(q, r):
    return mod_p(q, r) * mod_p((q - 1), MOD - r) * mod_p(1, gcd(r, MOD)) % MOD

@lru_cache(None)
def nLnq(q, r):
    i = 0
    q %= MOD
    p = 1
    while True:
        if pow(int(q), 2 * i, MOD) == 1:
            p *= nCr(q, i)
            q = r * (MOD - 1) - i * (MOD - 1)
        if q == 0:
            break
        i += 1
    return p

def good_array(N, A):
    count = defaultdict(int)
    for a in A:
        count[a] += 1

    dp = [0] * (N + 1)
    dp[0] = 1
    for freq in count.values():
        for i in range(freq, N + 1):
            dp[i] = sum(dp[j] * nLnq(i - j, freq) for j in range(freq - 1)) % MOD
    return dp[-1]

def dfs(pecs):
    prev = pecs[pecs[0]]
    if pecs[pecs[0]] == pecs[0]:
        return [[]]
    poss = [[] for _ in range(prev + 1)]
    for i in range(prev + 1):
        if pecs[i] > pecs[0]:
            poss[i] = dfs(pecs)
            for t in poss[i - 1]:
                poss[i].append([pecs[i]] + t)
        if pecs[pecs[0]] > pecs[i]:
            poss[i].append(pecs[:pecs[0] + 1] + pecs[pecs[0] + 1:i + 1] + pecs[0:i + 1])
    return poss[-1]

def solve(test_case):
    N = int(input())
    P = list(map(int, input().split()))
    quadruplets = dfs(P)
    print(good_array(N, quadruplets))

T = int(input())
