    xs = []
    vi = []
    vwind = []
    for i in range(n):
        x, v = map(int, input().split())
        xs.append(x)
        vi.append(v)
        vwind.append(sqrt(w**2 - v**2))
    positions = sorted(zip(xs, vi, vwind))

    def day_after(t):
        return abs(t) % w == 0

    def positions_after(t):
        return sorted(zip(t - 1 / 2, positions))

    dy = []
    for x0, v0, w0 in positions:
        dx = abs(x0)
        dy.append(dx / w0 if day_after(dx / w0) else -inf)

    def factors(t):
        a = b = 0
        c = t
        while c % 2 == 0:
            c >>= 1
            a += 1
        for i in range(3, int(sqrt(c))+1, 2):
            while c % i == 0:
                b += 1
                c //= i
        if c > 2:
            b += 1
        return a, b

    print(" ".join(map(str, sorted(map(factors, map(lambda t: (t**2 / (-w + t), t ** 2 / (-w - t)), sorted(set(map(lambda t, ps: t - ps[0], vwind), positions))))))))[:-2]

