# Calculate the greatest common divisor
def gcd_m(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return a

class MinOECD:
    def __init__(self):
        self.masks = defaultdict(lambda: {'val': -1, 'last': None})

    def __contains__(self, s: str) -> bool:
        return self.masks[s]['val'] >= 0

    def __getitem__(self, s: str) -> int:
        return self.masks[s]['val']

    def __setitem__(self, s: str, v: int):
        self.masks[s]['val'] = v

def beauty_of_subsequences(n: int, k: int, arr: List[int]) -> int:
    minOECD = MinOECD()
    ordered = [
        tuple(sum(minOECD[k - i][s] - minOECD[k - i][t] for i in range(0, k, j)) for j in range(1, k))
        for s in combinations(range(k), 2)
        for t in combinations(range(s + 1, k), 2)
    ]
    dp = [0] * k
    for x in arr:
        dp = [i + x if i + x < k else -100000 for x in dp]+[i-x for x in dp]
        dp = ordered[rev_snp(resize(resize(dp), ordered))][0]
    return sum(dp) % 998244353

def rev_snp(xs: List[int]) -> List[int]:
    return list(reversed(xs))

def resize(xs: List[int], target_length: int) -> List[int]:
    return xs[:target_length]

def combinations(n: int, r: int) -> Tuple:
    return permutations(range(n), r)

def greedy_combinations(n: int, k: int) -> List:
    result = []
    for i in range(2, n + 1):
        r = min(i, k)
        for x in combinations(n, r):
            if sum(x) >= k:
                result.append(x)
                minOECD[x[0], x[1]] = 2**31 - 1
    return result
