mod = 998244353

# Function to calculate binomial coefficient using lru_cache for memoization
@lru_cache(maxsize=None)
def binomial(n, k):
    return n * binomial(n - 1, k - 1) // k if k > 0 else 1

def lcm(a, b):
    return a * b // gcd(a, b)

def calculate_beauty(a, k):
    n = len(a)
    dp = [[0] * (k + 1) for _ in range(k + 1)]

    for sub in range(1, k + 1):
        dp[0][sub] = a[0] - a[1]

    for i in range(1, n):
        for sub in range(1, k + 1):
            dp[0][sub] = (dp[0][sub] + a[i] - a[i - 1]) % mod
            for j in range(sub):
                for p in range(1, min(i + 1, k)):
                    dp[max(p, j)][sub] = (dp[max(p, j)][sub] + dp[max(p, j - 1)][sub - 1] * p) % mod

    return dp[-1][-1]

